describe('Loading Skeleton Display During API Fetch', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display loading skeleton while API data is fetching', () => {
    // Intercept the API call
    cy.intercept('GET', '/api/user-data').as('fetchUserData');

    // Trigger the data fetch
    cy.get('[data-testid="load-button"]').click();

    // Verify loading skeleton is visible
    cy.get('[data-testid="loading-skeleton"]').should('be.visible');
    cy.get('[data-testid="skeleton-card"]').should('be.visible');
    cy.get('[data-testid="skeleton-text"]').should('be.visible');

    // Verify actual data is not yet visible
    cy.get('[data-testid="user-name"]').should('not.exist');
    cy.get('[data-testid="user-email"]').should('not.exist');

    // Wait for the API response
    cy.wait('@fetchUserData');

    // Verify loading skeleton is hidden after data loads
    cy.get('[data-testid="loading-skeleton"]').should('not.exist');

    // Verify actual data is now visible
    cy.get('[data-testid="user-name"]').should('be.visible');
    cy.get('[data-testid="user-email"]').should('be.visible');
  });

  it('should handle API error and display error message instead of skeleton', () => {
    // Intercept the API call and simulate an error
    cy.intercept('GET', '/api/user-data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('fetchUserDataError');

    // Trigger the data fetch
    cy.get('[data-testid="load-button"]').click();

    // Verify loading skeleton is briefly visible
    cy.get('[data-testid="loading-skeleton"]').should('be.visible');

    // Wait for the error response
    cy.wait('@fetchUserDataError');

    // Verify loading skeleton is hidden
    cy.get('[data-testid="loading-skeleton"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-text"]').should('contain', 'Internal Server Error');

    // Verify actual data is not displayed
    cy.get('[data-testid="user-name"]').should('not.exist');
    cy.get('[data-testid="user-email"]').should('not.exist');
  });
});
